import { defineConfig } from "vite-plus";

// The site reads docs in place from packages/*/docs (incl. the API reference generated by each
// package's build), and its config imports the built @mrmt/vitepress-plugin-sidebar.
const docsDependencies = [
  "@mrmt/vitepress-plugin-sidebar#build",
  "@mrmt/vite#build",
  "@mrmt/vite-ui#build",
  "@mrmt/vitest#build",
  "marmotte#build",
];

export default defineConfig({
  staged: {
    "*": "vp check --fix",
  },
  run: {
    tasks: {
      docs: { command: "vitepress dev docs", dependsOn: docsDependencies, cache: false },
      "build:docs": { command: "vitepress build docs", dependsOn: docsDependencies },
    },
  },
});
